<script lang="ts">
  import { label, unitLabel, choices, type Envelope } from './form.ts';
  let { field, fieldKey, pointer, sources, onchange, estimated = false }: { field: Envelope; fieldKey: string; pointer: string; sources: { source_id: string; title: string; kind?: string }[]; estimated?: boolean; onchange: (value: unknown, source: string, raw?: string) => void } = $props();
  const id = $derived('field' + pointer.replaceAll('/', '-'));
  const title = $derived(pointer.includes('/seasonality/') ? `${['January','February','March','April','May','June','July','August','September','October','November','December'][Number(fieldKey)]} demand factor` : label(fieldKey));
  let options = $derived(field.unit === 'boolean' ? [['true','Yes'],['false','No']] : choices[fieldKey]);
  function change(raw: string) {
    const value = raw === '' ? null : field.unit === 'boolean' ? raw === 'true' : ['text','ISO_date'].includes(field.unit) ? raw : Number(raw);
    onchange(value, field.source_ids[0] ?? sources[0]?.source_id ?? '', raw);
  }
</script>
<div class="field">
  <label for={id}>{title} <span>{unitLabel(field.unit)}</span></label>
  {#if options}<select {id} value={field.value === null ? '' : String(field.value)} onchange={e => change(e.currentTarget.value)}><option value="">Not yet known</option>{#each options as [value, title]}<option {value}>{title}</option>{/each}</select>
  {:else}<input {id} type={field.unit === 'ISO_date' ? 'date' : field.unit === 'text' ? 'text' : 'number'} step="any" value={field.value === null ? '' : String(field.value)} placeholder="Not yet known" oninput={e => change(e.currentTarget.value)} />{/if}
  <label class="source" for={id + '-source'}>Source</label><select id={id + '-source'} value={field.source_ids[0] ?? ''} onchange={e => onchange(field.value, e.currentTarget.value)}><option value="">Choose evidence or estimate</option>{#each sources.filter(source => source.kind !== 'spreadsheet_cell' || field.source_ids.includes(source.source_id)) as source}<option value={source.source_id}>{source.title}</option>{/each}</select>
  <small>{field.state.replaceAll('_', ' ')}{field.value !== null && (estimated || sources.some(s => field.source_ids.includes(s.source_id) && s.kind === 'owner_estimate')) ? ' · estimate' : ''}</small>
  <details><summary>Applicable dates</summary><p>{field.period === null ? 'No period supplied. Enter an as-of date or date range before saving a value.' : 'Preserve the date or coverage of this source fact.'}</p><label>As-of date<input type="date" value={field.period && 'as_of' in field.period ? field.period.as_of : ''} onchange={e => { field.period = e.currentTarget.value ? { as_of: e.currentTarget.value } : null; onchange(field.value, field.source_ids[0] ?? ''); }} /></label><label>Period starts<input type="date" value={field.period && 'start' in field.period ? field.period.start : ''} onchange={e => { field.period = { start: e.currentTarget.value, end: field.period && 'end' in field.period ? field.period.end : '' }; onchange(field.value, field.source_ids[0] ?? ''); }} /></label><label>Period ends<input type="date" value={field.period && 'end' in field.period ? field.period.end : ''} onchange={e => { field.period = { start: field.period && 'start' in field.period ? field.period.start : '', end: e.currentTarget.value }; onchange(field.value, field.source_ids[0] ?? ''); }} /></label></details>
</div>
<style>.field{display:grid;gap:.3rem;align-content:start}label{font-weight:600;font-size:.9rem}label span,small{display:block;font-size:.75rem;font-weight:400;color:#526a70}.source{font-size:.72rem;margin-top:.15rem;font-weight:400}input,select{width:100%;box-sizing:border-box;border:1px solid #b9c8c9;border-radius:6px;padding:.55rem;background:white;color:#17363b}small{color:#617271}.field{gap:6px}label{line-height:1.5}input,select{min-height:40px;font-size:13px}details{margin-top:4px}details>summary{font-size:12px;color:#607366}details p{font-size:12px;line-height:1.6}details label{margin-top:10px}</style>
